class Ticket {
  constructor(id, createdAt) { this.id = id; this.createdAt = createdAt; }
  toJSON() { return { id: this.id, created_at: this.createdAt.toISOString() }; }
  static fromJSON(o) { return new Ticket(o.id, new Date(o.created_at)); }
}

const wire = JSON.stringify(new Ticket(1, new Date()));   // toJSON()
const ticket = Ticket.fromJSON(JSON.parse(wire));         // reverse hook, same module
